#include <libbsa/libbsa.hpp>

#include <cstddef>
#include <cstdint>
#include <memory>
#include <mutex>
#include <span>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

namespace
{

  class byte_vector_sink final : public libbsa::payload_sink
  {
  public:
    libbsa::result<std::size_t> write(std::span<const std::byte> bytes) override
    {
      bytes_.insert(bytes_.end(), bytes.begin(), bytes.end());
      return bytes.size();
    }

    const std::vector<std::byte> &bytes() const noexcept { return bytes_; }

  private:
    std::vector<std::byte> bytes_;
  };

  class byte_vector_sink_factory final : public libbsa::bulk_extract_sink_factory
  {
  public:
    libbsa::result<std::unique_ptr<libbsa::payload_sink>> create(std::string_view path,
                                                                 const libbsa::entry_metadata &entry) override
    {
      // Bulk extraction may call the factory concurrently, so even example bookkeeping is protected.
      const std::lock_guard lock{mutex_};
      requested_paths_.push_back(std::string{path});
      observed_entries_.push_back(entry.path);
      std::unique_ptr<libbsa::payload_sink> sink = std::make_unique<byte_vector_sink>();
      return sink;
    }

    const std::vector<std::string> &requested_paths() const noexcept { return requested_paths_; }

    const std::vector<std::string> &observed_entries() const noexcept { return observed_entries_; }

  private:
    std::mutex mutex_;
    std::vector<std::string> requested_paths_;
    std::vector<std::string> observed_entries_;
  };

  libbsa::result<void> example_open_list_extract(std::string_view archive_host_path,
                                                 std::string_view archive_virtual_path,
                                                 libbsa::payload_sink &sink)
  {
    auto opened = libbsa::archive_reader::open(archive_host_path);
    if (!opened)
    {
      return opened.error();
    }

    auto reader = std::move(opened).value();
    auto metadata = reader.metadata();
    if (!metadata)
    {
      return metadata.error();
    }

    auto entries = reader.entries();
    if (!entries)
    {
      return entries.error();
    }

    auto found = reader.find(archive_virtual_path);
    if (!found)
    {
      return found.error();
    }
    if (!found.value())
    {
      return libbsa::error{libbsa::error_code::not_found, "archive path is not present"};
    }

    auto present = reader.contains(archive_virtual_path);
    if (!present)
    {
      return present.error();
    }
    if (!present.value())
    {
      return libbsa::error{libbsa::error_code::not_found, "archive path is not present"};
    }

    auto buffered_payload = reader.extract_bytes(archive_virtual_path);
    if (!buffered_payload)
    {
      return buffered_payload.error();
    }
    [[maybe_unused]] const auto buffered_payload_size = buffered_payload.value().size();

    return reader.extract(archive_virtual_path, sink);
  }

  libbsa::result<std::vector<libbsa::bulk_extract_entry_result>> example_bulk_extract(
      std::string_view archive_host_path,
      std::span<const std::string> archive_virtual_paths,
      libbsa::bulk_extract_sink_factory &sink_factory)
  {
    auto opened = libbsa::archive_reader::open(archive_host_path);
    if (!opened)
    {
      return opened.error();
    }

    std::vector<libbsa::bulk_extract_request> requests;
    requests.reserve(archive_virtual_paths.size());
    for (const auto &archive_virtual_path : archive_virtual_paths)
    {
      requests.push_back(libbsa::bulk_extract_request{archive_virtual_path});
    }

    libbsa::bulk_extract_options options;
    options.worker_count = 2U;

    auto reader = std::move(opened).value();
    return reader.extract_entries(requests, sink_factory, options);
  }

  libbsa::result<void> example_create_tes3_bsa(std::string_view source_host_path, std::string_view output_host_path)
  {
    libbsa::tes3_bsa_writer_options options;
    options.overwrite_existing = true;

    libbsa::tes3_bsa_writer writer{options};
    if (auto added = writer.add_file("book/readme.txt", source_host_path); !added)
    {
      return added.error();
    }

    libbsa::write_execution_options execution;
    execution.worker_count = 1U;
    return writer.write_to(output_host_path, execution);
  }

  libbsa::result<void> example_create_tes4_bsa(std::string_view source_host_path, std::string_view output_host_path)
  {
    libbsa::tes4_bsa_writer_options options;
    options.compression_policy = libbsa::archive_compression_policy::target_default;
    options.overwrite_existing = true;

    libbsa::tes4_bsa_writer writer{libbsa::tes4_bsa_target::skyrim_se, options};
    if (auto added = writer.add_file("meshes/example/example.nif",
                                     source_host_path,
                                     libbsa::entry_compression_policy::inherit);
        !added)
    {
      return added.error();
    }

    libbsa::write_execution_options execution;
    execution.worker_count = 2U;
    return writer.write_to(output_host_path, execution);
  }

  libbsa::result<void> example_create_ba2_gnrl(std::string_view source_host_path, std::string_view output_host_path)
  {
    libbsa::ba2_gnrl_writer_options options;
    options.compression = libbsa::archive_compression_policy::target_default;
    options.overwrite_existing = true;
    options.starfield_compression_method = 3U;

    libbsa::ba2_gnrl_writer writer{libbsa::ba2_gnrl_target::starfield_v3, options};
    if (auto added = writer.add_file("scripts/example/example.pex",
                                     source_host_path,
                                     libbsa::entry_compression_policy::compressed);
        !added)
    {
      return added.error();
    }

    libbsa::write_execution_options execution;
    execution.worker_count = 2U;
    return writer.write_to(output_host_path, execution);
  }

  libbsa::result<void> example_create_ba2_dx10(std::string_view dds_host_path, std::string_view output_host_path)
  {
    libbsa::ba2_dx10_writer_options options;
    options.overwrite_existing = true;
    options.starfield_compression_method = 3U;

    libbsa::ba2_dx10_writer writer{libbsa::ba2_dx10_target::starfield_v3, options};
    if (auto added = writer.add_file("textures/example/example_d.dds", dds_host_path); !added)
    {
      return added.error();
    }

    libbsa::write_execution_options execution;
    execution.worker_count = 2U;
    return writer.write_to(output_host_path, execution);
  }

  int example_handle_result_errors(std::string_view archive_host_path)
  {
    auto opened = libbsa::archive_reader::open(archive_host_path);
    if (opened)
    {
      return 0;
    }

    const auto code = opened.error().code;
    if (code == libbsa::error_code::io_error)
    {
      return 10;
    }
    if (code == libbsa::error_code::format_error)
    {
      return 20;
    }
    if (code == libbsa::error_code::unsupported)
    {
      return 30;
    }
    return 1;
  }

  libbsa::result<libbsa::validation_report> example_validate_archive(std::string_view archive_host_path)
  {
    libbsa::validation_options options;
    options.expected_type = libbsa::archive_type::bsa;
    options.validate_entry_extractability = true;

    auto report = libbsa::validate_archive(archive_host_path, options);
    if (!report)
    {
      return report.error();
    }

    for (const auto &warning : report.value().warnings)
    {
      if (warning.code == libbsa::compatibility_warning_code::compressed_sound_payload)
      {
        break;
      }
    }

    return report;
  }

  int example_link_representative_public_api()
  {
    std::vector<std::byte> bytes{std::byte{0x41}};

    auto opened = libbsa::archive_reader::open("consumer-smoke-missing.bsa");
    if (opened)
    {
      return 1;
    }

    auto validated = libbsa::validate_archive("consumer-smoke-missing.bsa");
    if (validated)
    {
      return 1;
    }

    libbsa::tes3_bsa_writer tes3_writer;
    if (!tes3_writer.add_bytes("meshes/consumer/link.nif", bytes))
    {
      return 1;
    }
    [[maybe_unused]] const auto &tes3_options = tes3_writer.options();

    libbsa::tes4_bsa_writer tes4_writer{libbsa::tes4_bsa_target::fallout3};
    if (!tes4_writer.add_bytes("meshes/consumer/link.nif", bytes))
    {
      return 1;
    }
    [[maybe_unused]] const auto tes4_target = tes4_writer.target();

    libbsa::ba2_gnrl_writer ba2_gnrl_writer{libbsa::ba2_gnrl_target::fallout4};
    if (!ba2_gnrl_writer.add_bytes("meshes/consumer/link.nif", bytes))
    {
      return 1;
    }
    [[maybe_unused]] const auto ba2_gnrl_target = ba2_gnrl_writer.target();

    libbsa::ba2_dx10_writer ba2_dx10_writer{libbsa::ba2_dx10_target::fallout4};
    [[maybe_unused]] const auto &ba2_dx10_options = ba2_dx10_writer.options();

    byte_vector_sink_factory factory;
    [[maybe_unused]] const auto &requested = factory.requested_paths();
    return 0;
  }

} // namespace

int main()
{
  if (example_link_representative_public_api() != 0)
  {
    return 1;
  }

  auto result = libbsa::validate_archive("consumer-smoke.bsa");
  if (result)
  {
    return 1;
  }

  return result.error().code == libbsa::error_code::io_error ? 0 : 1;
}

#pragma once

#include <cstddef>
#include <cstdint>
#include <memory>
#include <optional>
#include <span>
#include <string_view>

#include <libbsa/export.hpp>
#include <libbsa/result.hpp>

namespace libbsa
{

  /// TES4-family BSA archive target profiles supported by the write-new API.
  ///
  /// The selected profile controls archive version and target-specific default
  /// compression behavior without exposing raw archive flag bits to callers.
  enum class tes4_bsa_target
  {
    oblivion,
    fallout3,
    skyrim_se,
  };

  /// Archive-wide compression policy applied before per-entry overrides.
  ///
  /// `target_default` lets libbsa choose the target profile default while
  /// `all_raw` and `all_compressed` provide explicit compatibility-safe modes.
  enum class archive_compression_policy
  {
    target_default,
    all_raw,
    all_compressed,
  };

  /// Per-entry compression override relative to the archive-wide policy.
  ///
  /// `compressed` maps to the selected target profile's supported codec; codec
  /// tuning remains internal so public headers stay dependency-light.
  enum class entry_compression_policy
  {
    inherit,
    raw,
    compressed,
  };

  /// BA2 GNRL archive target profiles supported by the write-new API.
  ///
  /// The selected profile controls the serialized BA2 version and the default
  /// compression metadata used when entries inherit archive-wide policy.
  enum class ba2_gnrl_target
  {
    fallout4,
    starfield_v2,
    starfield_v3,
  };

  /// BA2 DX10/DDS texture archive target profiles supported by the write-new API.
  ///
  /// The selected profile controls the serialized BA2 texture archive version and
  /// target-routed compressed chunk codec while keeping codec details out of the
  /// public C++20 header surface.
  enum class ba2_dx10_target
  {
    fallout4,
    starfield_v3,
  };

  /// Write-call execution controls shared by public writer finalization APIs.
  ///
  /// Packing controls live on `write_to` calls rather than in target
  /// compatibility options. `worker_count == 1` preserves serial behavior,
  /// `worker_count > 1` opts into parallel-capable work for writer paths that
  /// support it, and `worker_count == 0` is invalid.
  ///
  /// Thread-safety: the options value is copied into `write_to`; the writer owns
  /// worker scheduling for that call. See `docs/thread-safety.md`.
  struct write_execution_options
  {
    /// Positive worker count requested for finalization work.
    std::uint32_t worker_count{1U};
  };

  /// Options controlling TES4-family write-new archive finalization.
  struct tes4_bsa_writer_options
  {
    /// Archive-wide compression behavior used by entries whose policy is `inherit`.
    archive_compression_policy compression_policy{archive_compression_policy::target_default};

    /// Emits target-compatible embedded file-name payload prefixes when true.
    bool embed_file_names{false};

    /// Shares identical stored payload regions only when explicitly enabled.
    bool deduplicate_payloads{false};

    /// Allows `write_to` to replace an existing regular host-path archive when true.
    bool overwrite_existing{false};
  };

  /// Options controlling TES3/Morrowind write-new archive finalization.
  struct tes3_bsa_writer_options
  {
    /// Allows `write_to` to replace an existing regular host-path archive when true.
    bool overwrite_existing{false};
  };

  /// Options controlling BA2 GNRL write-new archive finalization.
  struct ba2_gnrl_writer_options
  {
    /// Archive-wide compression behavior used by entries whose policy is `inherit`.
    archive_compression_policy compression = archive_compression_policy::target_default;

    /// Allows `write_to` to replace an existing regular host-path archive when true.
    bool overwrite_existing = false;

    /// Shares identical stored payload regions only when explicitly enabled.
    bool deduplicate_payloads = false;

    /// Starfield v2/v3 Unknown1 header value; ignored for Fallout 4 v1 targets.
    ///
    /// xEdit/BSArchPro-derived Starfield write defaults use `1`, while callers can
    /// override this compatibility field when preserving known archive metadata.
    std::uint32_t starfield_unknown1 = 1U;

    /// Starfield v2/v3 Unknown2 header value; ignored for Fallout 4 v1 targets.
    std::uint32_t starfield_unknown2 = 0U;

    /// Starfield v3 archive-wide compression method; ignored by v1/v2 targets.
    ///
    /// Method `3` maps compressed GNRL entries to raw LZ4 blocks, while method `0`
    /// maps them to deflate. Unsupported methods fail during finalization.
    std::uint32_t starfield_compression_method = 3U;
  };

  /// Options controlling BA2 DX10/DDS write-new archive finalization.
  struct ba2_dx10_writer_options
  {
    /// Allows `write_to` to replace an existing regular host-path archive when true.
    bool overwrite_existing = false;

    /// Shares identical final stored texture chunk payloads only when explicitly enabled.
    bool deduplicate_payloads = false;

    /// Archive-wide decoded byte cap for texture chunk planning.
    ///
    /// `0` selects the reference-derived default chunking behavior; nonzero values
    /// ask the writer to split at mip boundaries where the requested cap is representable.
    std::uint32_t max_decoded_chunk_bytes = 0U;

    /// Starfield v3 Unknown1 header value; ignored for Fallout 4 v1 targets.
    ///
    /// xEdit/BSArchPro-derived Starfield write defaults use `1`, while callers can
    /// override this compatibility field when preserving known archive metadata.
    std::uint32_t starfield_unknown1 = 1U;

    /// Starfield v3 Unknown2 header value; ignored for Fallout 4 v1 targets.
    std::uint32_t starfield_unknown2 = 0U;

    /// Starfield v3 archive-wide compression method; ignored by Fallout 4 v1 targets.
    ///
    /// Method `3` is the default compressed chunk route for Starfield v3 texture
    /// archives, while method `0` remains available for compatibility cases.
    std::uint32_t starfield_compression_method = 3U;
  };

  /// Per-entry options for BA2 GNRL payload and record metadata.
  struct ba2_gnrl_entry_options
  {
    /// Per-entry compression override relative to the archive-wide policy.
    entry_compression_policy compression = entry_compression_policy::inherit;

    /// Optional advanced BA2 GNRL record-flags override for compatibility cases.
    ///
    /// Hashes, payload offsets, stored sizes, raw sizes, and the `BAADF00D`
    /// sentinel remain writer-owned and are not caller-controlled.
    std::optional<std::uint32_t> record_flags = std::nullopt;
  };

  /// Public writer for creating new TES4-family BSA archives.
  ///
  /// Entries are added with explicit archive-internal paths and finalized to a
  /// host-path archive. Memory-buffer entries are copied into writer-owned state.
  ///
  /// Thread-safety: separately constructed or moved-to writer objects may be used
  /// concurrently, but mutation is not concurrent with other mutation or
  /// `write_to` on the same writer object. See `docs/thread-safety.md`.
  class tes4_bsa_writer
  {
  public:
    /// Creates a writer for `target` using default writer options.
    LIBBSA_API explicit tes4_bsa_writer(tes4_bsa_target target);

    /// Creates a writer for `target` using the supplied compatibility options.
    LIBBSA_API explicit tes4_bsa_writer(tes4_bsa_target target, tes4_bsa_writer_options options);

    /// Destroys the writer and releases any staged archive state it owns.
    LIBBSA_API ~tes4_bsa_writer();

    /// Copying is disabled because writer copies would alias mutable staged entries.
    tes4_bsa_writer(const tes4_bsa_writer &) = delete;

    /// Copy assignment is disabled because writer copies would alias mutable staged entries.
    tes4_bsa_writer &operator=(const tes4_bsa_writer &) = delete;

    /// Transfers staged entries and options from `other`; `other` is valid only for destruction or reassignment.
    LIBBSA_API tes4_bsa_writer(tes4_bsa_writer &&other) noexcept;

    /// Replaces this writer by taking staged entries and options from `other`.
    ///
    /// After the move, `other` is valid only for destruction or reassignment.
    LIBBSA_API tes4_bsa_writer &operator=(tes4_bsa_writer &&other) noexcept;

    /// Returns the target profile selected for this writer.
    [[nodiscard]] LIBBSA_API tes4_bsa_target target() const noexcept;

    /// Returns the immutable writer options selected at construction time.
    [[nodiscard]] LIBBSA_API const tes4_bsa_writer_options &options() const noexcept;

    /// Adds a host-file payload with an explicit archive-internal path.
    ///
    /// Implementations validate both paths and report expected I/O or format
    /// failures through `result<void>` instead of throwing for caller data errors.
    LIBBSA_API result<void> add_file(std::string_view archive_path,
                                     std::string_view host_path,
                                     entry_compression_policy compression = entry_compression_policy::inherit);

    /// Adds bytes copied from caller memory with an explicit archive-internal path.
    ///
    /// The writer owns an independent copy after this call, so callers may release
    /// or mutate the original memory before `write_to` is called.
    LIBBSA_API result<void> add_bytes(std::string_view archive_path,
                                      std::span<const std::byte> bytes,
                                      entry_compression_policy compression = entry_compression_policy::inherit);

    /// Finalizes the writer state into a new archive at `host_path`.
    ///
    /// Existing destinations fail unless `tes4_bsa_writer_options::overwrite_existing`
    /// was enabled. Publication uses a writer-owned temporary directory beside `host_path`,
    /// overwrites only supported regular-file destinations, rejects detectable reparse points,
    /// and returns compression or I/O failures as structured errors.
    LIBBSA_API result<void> write_to(std::string_view host_path) const;

    /// Finalizes the writer state using explicit write-call execution controls.
    ///
    /// `execution.worker_count` must be positive. A value of `1` preserves the
    /// serial behavior and output-publication policy of the one-argument overload.
    LIBBSA_API result<void> write_to(std::string_view host_path, write_execution_options execution) const;

  private:
    struct state;

    std::unique_ptr<state> state_;
  };

  /// Public writer for creating new TES3/Morrowind BSA archives.
  ///
  /// TES3 writer output is raw/uncompressed. The public surface intentionally has
  /// no compression, dedupe, or embedded-name controls because Morrowind BSA
  /// archives use one raw payload per archive entry.
  ///
  /// Thread-safety: separately constructed or moved-to writer objects may be used
  /// concurrently, but mutation is not concurrent with other mutation or
  /// `write_to` on the same writer object. See `docs/thread-safety.md`.
  class tes3_bsa_writer
  {
  public:
    /// Creates a raw/uncompressed TES3 writer using default writer options.
    LIBBSA_API tes3_bsa_writer();

    /// Creates a raw/uncompressed TES3 writer using explicit finalization options.
    LIBBSA_API explicit tes3_bsa_writer(tes3_bsa_writer_options options);

    /// Destroys the writer and releases any staged archive state it owns.
    LIBBSA_API ~tes3_bsa_writer();

    /// Copying is disabled because writer copies would alias mutable staged entries.
    tes3_bsa_writer(const tes3_bsa_writer &) = delete;

    /// Copy assignment is disabled because writer copies would alias mutable staged entries.
    tes3_bsa_writer &operator=(const tes3_bsa_writer &) = delete;

    /// Transfers staged entries and options from `other`; `other` is valid only for destruction or reassignment.
    LIBBSA_API tes3_bsa_writer(tes3_bsa_writer &&other) noexcept;

    /// Replaces this writer by taking staged entries and options from `other`.
    ///
    /// After the move, `other` is valid only for destruction or reassignment.
    LIBBSA_API tes3_bsa_writer &operator=(tes3_bsa_writer &&other) noexcept;

    /// Returns the immutable TES3 writer options selected at construction time.
    [[nodiscard]] LIBBSA_API const tes3_bsa_writer_options &options() const noexcept;

    /// Adds a host-file payload with an explicit TES3 archive-internal path.
    ///
    /// The archive path and non-empty host path are validated at add time; source
    /// file existence is checked when `write_to` finalizes the archive.
    LIBBSA_API result<void> add_file(std::string_view archive_path, std::string_view host_path);

    /// Adds bytes copied from caller memory with an explicit TES3 archive-internal path.
    ///
    /// The writer owns an independent copy after this call, so callers may release
    /// or mutate the original memory before `write_to` is called.
    LIBBSA_API result<void> add_bytes(std::string_view archive_path, std::span<const std::byte> bytes);

    /// Finalizes the writer state into a raw/uncompressed TES3 archive at `host_path`.
    ///
    /// Existing destinations fail unless `tes3_bsa_writer_options::overwrite_existing`
    /// was enabled. Publication uses a writer-owned temporary directory beside `host_path`,
    /// overwrites only supported regular-file destinations, rejects detectable reparse points,
    /// and returns validation or I/O failures as structured errors.
