{"purpose":"s05_requirements_status_summary","runtime":"python","script":"from pathlib import Path
p=Path('.gsd/REQUIREMENTS.md')
text=p.read_text(encoding='utf-8',errors='ignore')
for rid in ['R001','R002','R003','R004','R005','R006','R007','R008','R009','R011','R012','R013']:
    idx=text.find(rid)
    if idx==-1:
        print(f'{rid}: missing')
        continue
    # Print heading block first ~12 lines from heading containing rid
    start=text.rfind('\n##',0,idx)
    if start==-1: start=max(0,idx-120)
    end=text.find('\n##', idx+len(rid))
    block=text[start:end if end!=-1 else len(text)].splitlines()
    print(f'--- {rid} ---')
    for line in block[:14]:
        if any(key in line.lower() for key in ['status','class','description','validation','notes','id:', '##', '**status**','source']):
            print(line[:240])
    # fallback first lines
    if len(block)<3:
        print('\n'.join(block[:5]))
print('DONE')","timeout_ms":120000}
